// Pull campaign stats from a third-party API, safely
final class SyncCampaignStats implements ShouldQueue
{
    use Dispatchable, InteractsWithQueue, Queueable;

    public int $tries = 5;
    public array $backoff = [10, 60, 300];

    public function __construct(
        public readonly Campaign $campaign,
    ) {}

    public function handle(AdsClient $ads): void
    {
        $stats = $ads->statsFor($this->campaign->external_id);

        // Idempotent: a second run updates the same row
        CampaignStat::updateOrCreate(
            ['campaign_id' => $this->campaign->id,
             'date' => $stats->date],
            ['impressions' => $stats->impressions,
             'clicks' => $stats->clicks],
        );
    }
}

type Result<T> =
  | { ok: true; data: T }
  | { ok: false; error: string };

let ctrl: AbortController | null = null;

export async function search(
  q: string,
): Promise<Result<Candidate[]>> {
  ctrl?.abort();          // cancel the last search
  ctrl = new AbortController();
  const url = `/api/candidates?q=${encodeURIComponent(q)}`;
  try {
    const res = await fetch(url, { signal: ctrl.signal });
    if (!res.ok) {
      return { ok: false, error: `HTTP ${res.status}` };
    }
    return { ok: true, data: await res.json() };
  } catch (e) {
    if (e instanceof DOMException
        && e.name === 'AbortError') {
      return { ok: false, error: 'cancelled' };
    }
    throw e;
  }
}

// Vue 3: the component is the view model;
// the template binds to its state.
<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'

const props = defineProps<{ campaignId: number }>()
const stats = ref<Stat[]>([])
const loading = ref(true)
const ctr = computed(() => {
  const sum = (k: 'impressions' | 'clicks') =>
    stats.value.reduce((n, s) => n + s[k], 0)
  const imps = sum('impressions')
  const clicks = sum('clicks')
  return imps ? (clicks / imps) * 100 : 0
})

